CREATE TABLE users (id VARCHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at VARCHAR(32) NOT NULL);
CREATE TABLE organizations (id VARCHAR(36) PRIMARY KEY, name VARCHAR(150) NOT NULL, logo_url TEXT NOT NULL, kind VARCHAR(20) NOT NULL, created_at VARCHAR(32) NOT NULL);
CREATE TABLE memberships (organization_id VARCHAR(36) NOT NULL, user_id VARCHAR(36) NOT NULL, role VARCHAR(20) NOT NULL, created_at VARCHAR(32) NOT NULL, PRIMARY KEY(organization_id,user_id), FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE subscriptions (organization_id VARCHAR(36) PRIMARY KEY, plan_id VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL, publication_limit INTEGER NOT NULL, updated_at VARCHAR(32) NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE sessions (token_hash VARCHAR(64) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, organization_id VARCHAR(36) NOT NULL, csrf_token VARCHAR(80) NOT NULL, expires_at BIGINT NOT NULL, created_at VARCHAR(32) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE invitations (id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL, email VARCHAR(254) NOT NULL, role VARCHAR(20) NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at BIGINT NOT NULL, accepted_at VARCHAR(32), created_at VARCHAR(32) NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE properties (id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL, title VARCHAR(120) NOT NULL, type VARCHAR(40) NOT NULL, operation VARCHAR(20) NOT NULL, currency VARCHAR(3) NOT NULL, price_minor BIGINT NOT NULL, region VARCHAR(2) NOT NULL, commune VARCHAR(100) NOT NULL, sector VARCHAR(150) NOT NULL, private_address VARCHAR(250) NOT NULL, area DECIMAL(15,2) NOT NULL, beds INTEGER NOT NULL, baths INTEGER NOT NULL, description TEXT NOT NULL, images_json TEXT NOT NULL, status VARCHAR(20) NOT NULL, version INTEGER NOT NULL, deleted_at VARCHAR(32), created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL, UNIQUE(id,organization_id), FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE INDEX properties_tenant ON properties(organization_id,status,deleted_at);
CREATE INDEX properties_public ON properties(status,region,operation,type);
CREATE TABLE leads (id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL, property_id VARCHAR(36) NOT NULL, name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL, phone VARCHAR(30) NOT NULL, note TEXT NOT NULL, stage VARCHAR(30) NOT NULL, consent_version VARCHAR(100) NOT NULL, consent_at VARCHAR(32) NOT NULL, version INTEGER NOT NULL, created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL, UNIQUE(id,organization_id), FOREIGN KEY(property_id,organization_id) REFERENCES properties(id,organization_id));
CREATE INDEX leads_tenant ON leads(organization_id,created_at);
CREATE TABLE visits (id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL, property_id VARCHAR(36) NOT NULL, lead_id VARCHAR(36) NOT NULL, agent_id VARCHAR(36) NOT NULL, starts_at BIGINT NOT NULL, ends_at BIGINT NOT NULL, note TEXT NOT NULL, status VARCHAR(20) NOT NULL, version INTEGER NOT NULL, created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL, FOREIGN KEY(property_id,organization_id) REFERENCES properties(id,organization_id), FOREIGN KEY(lead_id,organization_id) REFERENCES leads(id,organization_id), FOREIGN KEY(organization_id,agent_id) REFERENCES memberships(organization_id,user_id));
CREATE INDEX visits_calendar ON visits(organization_id,agent_id,starts_at,ends_at,status);
CREATE TABLE projects (id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL, name VARCHAR(150) NOT NULL, region VARCHAR(2) NOT NULL, commune VARCHAR(100) NOT NULL, description TEXT NOT NULL, status VARCHAR(20) NOT NULL, version INTEGER NOT NULL, created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL, UNIQUE(id,organization_id), FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE units (id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL, project_id VARCHAR(36) NOT NULL, code VARCHAR(60) NOT NULL, type VARCHAR(40) NOT NULL, currency VARCHAR(3) NOT NULL, price_minor BIGINT NOT NULL, area DECIMAL(15,2) NOT NULL, beds INTEGER NOT NULL, baths INTEGER NOT NULL, status VARCHAR(20) NOT NULL, version INTEGER NOT NULL, created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL, UNIQUE(project_id,code), FOREIGN KEY(project_id,organization_id) REFERENCES projects(id,organization_id));
CREATE TABLE broker_profiles (organization_id VARCHAR(36) PRIMARY KEY, active INTEGER NOT NULL, regions_json TEXT NOT NULL, communes_json TEXT NOT NULL, operations_json TEXT NOT NULL, types_json TEXT NOT NULL, presentation TEXT NOT NULL, contact_email VARCHAR(254) NOT NULL, joined_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE owner_requests (id VARCHAR(36) PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL, phone VARCHAR(30) NOT NULL, region VARCHAR(2) NOT NULL, commune VARCHAR(100) NOT NULL, operation VARCHAR(20) NOT NULL, type VARCHAR(40) NOT NULL, note TEXT NOT NULL, consent_version VARCHAR(100) NOT NULL, manage_token_hash VARCHAR(64) NOT NULL, created_at VARCHAR(32) NOT NULL);
CREATE TABLE broker_requests (id VARCHAR(36) PRIMARY KEY, owner_request_id VARCHAR(36) NOT NULL, organization_id VARCHAR(36) NOT NULL, status VARCHAR(20) NOT NULL, created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL, UNIQUE(owner_request_id,organization_id), FOREIGN KEY(owner_request_id) REFERENCES owner_requests(id), FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE INDEX broker_requests_tenant ON broker_requests(organization_id,status);
CREATE TABLE audit_events (id VARCHAR(36) PRIMARY KEY, organization_id VARCHAR(36) NOT NULL, actor_id VARCHAR(36), action VARCHAR(80) NOT NULL, entity_type VARCHAR(40) NOT NULL, entity_id VARCHAR(80) NOT NULL, request_id VARCHAR(36) NOT NULL, created_at VARCHAR(32) NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE INDEX audit_tenant ON audit_events(organization_id,created_at);
CREATE TABLE rate_limits (bucket VARCHAR(64) PRIMARY KEY, hits INTEGER NOT NULL, expires_at BIGINT NOT NULL);
